/* From Uiverse.io by Jedi-hongbin - Tags: icon, button */
.__UIV_SCOPE__ button {
 display: flex;
 height: 3em;
 width: 100px;
 align-items: center;
 justify-content: center;
 background-color: #eeeeee4b;
 border-radius: 3px;
 letter-spacing: 1px;
 transition: all 0.2s linear;
 cursor: pointer;
 border: none;
 background: #fff;
}

.__UIV_SCOPE__ button > svg {
 margin-right: 5px;
 margin-left: 5px;
 font-size: 20px;
 transition: all 0.4s ease-in;
}

.__UIV_SCOPE__ button:hover > svg {
 font-size: 1.2em;
 transform: translateX(-5px);
}

.__UIV_SCOPE__ button:hover {
 box-shadow: 9px 9px 33px #d1d1d1, -9px -9px 33px #ffffff;
 transform: translateY(-2px);
}
